return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Polish','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-01 20:06+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'pl_PL','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10 >= 2 && n%10<=4 &&(n%100<10||n%100 >= 20)? 1 : 2);','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['Lingua Forge'=>'Lingua Forge','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Wielojęzyczne routingi, meta tagi SEO i narzędzia AI do treści dla WordPress. Łączy wykrywanie języka, routing URL, hreflang, opisy meta oraz funkcje AI do wycinków, meta i tłumaczeń.','Uli Hake'=>'Uli Hake','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Tłumacz','Lingua Forge — Quick Translate'=>'Lingua Forge — Szybkie tłumaczenie','Informative'=>'Informacyjne','Persuasive'=>'Przekonywujące','Storytelling'=>'Opowiadanie','Technical'=>'Techniczne','Conversational'=>'Konwersacyjne','Permission denied.'=>'Odmowa dostępu.','Cannot determine target language from slug.'=>'Nie można określić docelowego języka na podstawie slug.','Invalid post type.'=>'Nieprawidłowy typ wpisu.','Invalid or primary language.'=>'Nieprawidłowy lub główny język.','Template not found or not stored in the database.'=>'Szablon nie został znaleziony lub nie jest zapisany w bazie danych.','Template has no content.'=>'Szablon nie ma treści.','No internal links found to update.'=>'Nie znaleziono wewnętrznych linków do aktualizacji.','%d link updated.'=>'%d link zaktualizowany.' . "\0" . '%d linków zaktualizowanych.' . "\0" . '','No language-specific template parts found to map.'=>'Nie znaleziono części szablonu specyficznych dla języka do mapowania.','No template part references needed updating.'=>'Nie ma potrzeby aktualizacji odwołań do części szablonu.','%d part reference updated.'=>'%d odwołanie do części zaktualizowane.' . "\0" . '%d odwołań do części zaktualizowanych.' . "\0" . '','Invalid language.'=>'Nieprawidłowy język.','Template part not found or not stored in the database.'=>'Część szablonu nie została znaleziona lub nie jest zapisana w bazie danych.','Template part has no content.'=>'Część szablonu nie ma treści.','No navigation references needed updating.'=>'Nie ma potrzeby aktualizacji odwołań do nawigacji.','%d navigation reference updated.'=>'%d odwołanie do nawigacji zaktualizowane.' . "\0" . '%d odwołań do nawigacji zaktualizowanych.' . "\0" . '','No AI provider configured.'=>'Nie skonfigurowano dostawcy AI.','Missing pattern name or language.'=>'Brak nazwy wzoru lub języka.','Pattern not found.'=>'Wzór nie został znaleziony.','Pattern has no content to translate.'=>'Wzór nie ma treści do tłumaczenia.','AI provider returned an empty response.'=>'Dostawca AI zwrócił pustą odpowiedź.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Wzór został przetłumaczony i zapisany. Skopiuj treść do swojego wpisu CPT za pomocą edytora bloków lub użyj go jako punktu wyjścia dla wielokrotnego bloku.','Invalid template type.'=>'Nieprawidłowy typ szablonu.','Template "%s" already exists.'=>'Szablon "%s" już istnieje.','"%s" created.'=>'"%s" został utworzony.','Invalid template part.'=>'Nieprawidłowa część szablonu.','Template part "%s" already exists.'=>'Część szablonu "%s" już istnieje.','"%1$s" created. %2$d template updated.'=>'"%1$s" został utworzony. %2$d szablonów zaktualizowanych.' . "\0" . '"%1$s" został utworzony. %2$d szablonów zaktualizowanych.' . "\0" . '','Page'=>'Strona','Single'=>'Pojedynczy','Search'=>'Szukaj','Search Results'=>'Wyniki wyszukiwania','Archive'=>'Archiwum','Front Page'=>'Strona główna','Single: %s'=>'Pojedynczy: %s','Single %s'=>'Pojedynczy %s','Archive: %s'=>'Archiwum: %s','%s Archive'=>'%s Archiwum','No source content found to translate.'=>'Nie znaleziono treści źródłowej do tłumaczenia.','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Przetłumaczono. Przejrzyj w Edytorze Stron — linki wewnętrzne, adresy URL nawigacji i szablony nie są automatycznie aktualizowane.','Navigation not found.'=>'Nawigacja nie znaleziona.','Navigation has no content to translate.'=>'Nawigacja nie zawiera treści do tłumaczenia.','"%1$s %2$s" saved.'=>'"%1$s %2$s" zapisano.','Translate page…'=>'Tłumacz stronę…','Generate content…'=>'Generuj treść…','AI Behaviour Preset'=>'Predefiniowany zachowanie AI','Custom'=>'Niestandardowe','Global default (%s)'=>'Domyślny globalny (%s)','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Nadpisuje preset AI dla tłumaczenia i generowania treści na tej stronie. Instrukcje niestandardowe dla całej witryny (Ustawienia → Zachowanie) są zawsze dodawane do każdego żądania, niezależnie od tego wyboru.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Nadpisuje preset AI dla tłumaczenia i generowania treści na tej stronie. Wszystkie inne funkcje zawsze korzystają z globalnego preset.','Close'=>'Zamknij','Translate missing'=>'Brak tłumaczenia','From'=>'Od','Retranslate'=>'Przetłumacz ponownie','Translating…'=>'Tłumaczenie w toku…','Retranslating…'=>'Ponowne tłumaczenie…','✓ Done'=>'✓ Zrobione','Error'=>'Błąd','Navigation posts are translated via the Router tab, not this button.'=>'Posty nawigacji są tłumaczone przez zakładkę Router, a nie tym przyciskiem.','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Tworzenie tłumaczeń dla typu posta "%s" wymaga aktywnej integracji. Upewnij się, że wymagana integracja jest zainstalowana i aktywna.','No %s version found in this translation group.'=>'Nie znaleziono wersji %s w tej grupie tłumaczeń.','AI Usage'=>'Użycie AI','Today'=>'Dziś','Last 7 days'=>'Ostatnie 7 dni','Last 30 days'=>'Ostatnie 30 dni','All time'=>'Wszystko','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Zużycie tokenów podsumowane według funkcji, dostawcy i modelu. Rejestrowane przy każdym udanym wywołaniu AI; pingi Test Connection są celowo wykluczone, aby nie zniekształcały sum. Podstawowa tabela agreguje dane dziennie — wybierz okno poniżej, aby je wyświetlić.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Jeszcze nie zarejestrowano użycia AI. Gdy edytor wykona tłumaczenie, wygeneruje opis meta lub skorzysta z innej funkcji AI, sumy pojawią się tutaj.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Nie zarejestrowano użycia AI w wybranym oknie (%s). Wybierz szerszy zakres powyżej.','Feature'=>'Funkcja','Provider'=>'Dostawca','Model'=>'Model','Requests'=>'Żądania','Input tokens'=>'Tokeny wejściowe','Output tokens'=>'Tokeny wyjściowe','Total tokens'=>'Razem tokenów','Total'=>'Razem','API Keys'=>'Klucze API','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Klucze są szyfrowane za pomocą AES-256-CBC przed zapisaniem w bazie danych WordPress. Sekret szyfrowania pochodzi z Twoich soli uwierzytelniania WordPress (wp-config.php), więc klucze w formacie tekstowym nigdy nie trafiają do bazy danych.','API Key'=>'Klucz API','Paste your API key…'=>'Wklej swój klucz API…','✓ Configured'=>'✓ Skonfigurowano','✗ Not configured'=>'✗ Nie skonfigurowano','Test connection'=>'Testuj połączenie','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Pozostaw puste, aby zachować istniejący klucz. Wprowadź nową wartość, aby go zastąpić.','Remove stored key'=>'Usuń zapisany klucz','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Ten klucz jest obecnie dostarczany przez serwer %s i nie można go usunąć tutaj. Wprowadź nowy klucz powyżej, aby nadpisać go wartością z bazy danych.','environment variable'=>'zmienna środowiskowa','PHP constant'=>'stała PHP','Alternative (server-side):'=>'Alternatywnie (po stronie serwera):','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Możesz również definiować klucze jako stałe lub zmienne środowiskowe (np. w wp-config.php). Te źródła są automatycznie używane jako zapasowe, gdy nie ma zapisanej klucza w bazie danych.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Aby użyć własnego sekretu szyfrowania (zamiast wyprowadzonej wartości wp_salt), dodaj to do wp-config.php:','Unknown provider.'=>'Nieznany dostawca.','No API key configured for this provider.'=>'Dla tego dostawcy nie skonfigurowano klucza API.','Could not instantiate the provider.'=>'Nie można utworzyć instancji dostawcy.','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Dostawca nie zwrócił tekstu. Sprawdź dziennik błędów WordPress, aby uzyskać szczegółowy powód awarii.','Behavior'=>'Zachowanie','Block Editor'=>'Edytor bloków','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge domyślnie ogranicza dwie funkcje Gutenberga, aby zachować spójne zachowanie redakcyjne w różnych językach. Zaznacz tutaj, gdy potrzebujesz pełnych możliwości Gutenberga / FSE.','Block locking'=>'Blokada','Allow editors to lock individual blocks'=>'Zezwól redaktorom na blokowanie poszczególnych bloków','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Ponownie włącza canLockBlocks Gutenberga. Przydatne dla szablonów redakcyjnych, które muszą zapobiegać przesuwaniu lub usuwaniu określonych bloków.','Template mode'=>'Tryb szablonu','Allow Gutenberg template-editing mode on post screens'=>'Zezwól na tryb edycji szablonów Gutenberga na ekranach wpisów','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Ponownie włącza supportsTemplateMode. Kluczowe dla pełnych przepływów pracy edycji całej strony, gdzie celowo nadpisuje się szablony na poziomie wpisu.','Compliance Preset'=>'Predefiniowany ustawienie zgodności','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Tryb ścisłego zachowania dla treści prawnych, regulacyjnych, medycznych lub technicznych. Gdy jest włączony, każda funkcja AI używa niskiej temperatury próbkowania i dodaje poniższy dodatek do swojego promptu systemowego — terminologia, numery artykułów, jednostki, nazwy marek i język regulacyjny są zachowywane dokładnie, a nie parafrazowane.','Global AI preset'=>'Globalny preset AI','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, na funkcję','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Ustawia domyślne zachowanie AI dla wszystkich funkcji w całej witrynie. Poszczególne wpisy mogą to nadpisać dla tłumaczeń i generowania treści za pomocą meta boxa Lingua Forge.','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard używa własnej dostrojonej temperatury dla każdej funkcji: Tłumaczenie T=0.2 (precyzyjne), Szybkie tłumaczenie T=0.4, Generator treści T=0.6 (kreatywne). Pozostałe preset\'y stosują jedną stałą temperaturę dla wszystkich funkcji.','Technical / Scientific instructions'=>'Instrukcje techniczne / naukowe','Legal / Compliance instructions'=>'Instrukcje prawne / zgodności','Creative / Marketing instructions'=>'Instrukcje kreatywne / marketingowe','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Pozostaw puste, aby użyć wbudowanego domyślnego ustawienia. Wyczyszczenie zapisanej nadpisanej wartości przywraca domyślną wartość przy następnym zapisie.','View built-in default'=>'Wyświetl wbudowany domyślny','Translation Memory'=>'Pamięć tłumaczeń','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Buforuj tłumaczone odpowiedniki na poziomie bloków, aby wielokrotne treści (wspólne stopki, paski boczne, akordeony, sekcje prawne z dużą ilością boilerplate\'u) nie wymagały wywołania API za każdym razem. Gdy funkcja jest włączona, przepływ tłumaczenia analizuje każdy wpis na bloki, sprawdza je w pamięci podręcznej i wysyła tylko niepamiętane bloki do AI w jednym zgrupowanym żądaniu. Edycje słownika i zmiany presetów zgodności automatycznie unieważniają odpowiednie tłumaczenia w pamięci podręcznej. Wyświetl statystyki i wyczyść pamięć podręczną w sekcji Utrzymanie.','Enable block-level translation cache reuse across posts'=>'Włącz ponowne użycie pamięci podręcznej tłumaczeń na poziomie bloków między wpisami','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Obecnie pomijane dla wpisów korzystających z atrybutów blok-comment (np. wp:details, pola podsumowania) — przechodzą do istniejącej ścieżki tłumaczenia wywołania pojedynczego.','General'=>'Ogólne','Light'=>'Lekki','Meta Description, Excerpt Generator'=>'Meta Description, Generator fragmentów','Quality'=>'Jakość','Translation, Content Generator'=>'Tłumaczenie, Generator treści','Active Provider'=>'Aktywny dostawca','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Obecnie dziedziczone z constanty %s. Wybranie wartości tutaj nadpisze to.','Models'=>'Modele','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Funkcje są pogrupowane w dwie warstwy. Wprowadź dokładny identyfikator modelu dla każdej warstwy i dostawcy. Pozostaw pole puste, aby użyć wbudowanego domyślnego (pokazanego jako placeholder). Tylko modele aktywnego dostawcy są wywoływane podczas działania — skonfiguruj pozostałe wcześniej, jeśli planujesz zmianę.','active'=>'aktywne','overridden'=>'nadpisane','Tip: to reset a model to the built-in default, clear the field and save.'=>'Wskazówka: aby zresetować model do wbudowanego domyślnego, wyczyść pole i zapisz.','Glossary'=>'Słownik','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tablica terminologii zarządzana przez użytkownika dla pary językowej. Wpisy są dodawane do promptu systemu tłumaczeń, aby AI używało preferowanych terminów konsekwentnie — kluczowe dla słownictwa dziedzinowego ("kWp", "PPA", "punkt połączenia"), nazw marek, które nie mogą być tłumaczone, oraz ustandaryzowanej frazeologii regulacyjnej. Oba pola językowe są opcjonalne: pozostaw "Język źródłowy" pusty, aby zastosować wpis niezależnie od języka, z którego tłumaczysz; pozostaw "Język docelowy" pusty, aby zastosować go do wszystkich języków docelowych naraz.','Glossary entry added.'=>'Wpis słownika dodany.','Glossary entry removed.'=>'Wpis słownika usunięty.','Could not add entry: source term and target term are required.'=>'Nie można dodać wpisu: wymagany jest termin źródłowy i termin docelowy.','Could not save the glossary entry.'=>'Nie można zapisać wpisu słownika.','Source language'=>'Język źródłowy','— Any —'=>'— Dowolny —','Target language'=>'Język docelowy','— Any target —'=>'— Dowolny język docelowy —','Filter'=>'Filtr','Reset'=>'Resetuj','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Brak wpisów słownika pasujących do obecnego filtra. Wyczyść filtr, aby zobaczyć wszystkie wpisy, lub dodaj nowy wpis poniżej.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Brak jeszcze wpisów słownika. Dodaj jeden poniżej, aby zacząć egzekwować terminologię w tłumaczeniach.','Source term'=>'Termin źródłowy','Target term'=>'Termin docelowy','Source lang'=>'Język źródłowy','Target lang'=>'Język docelowy','Notes'=>'Uwagi','any'=>'dowolny','Delete this glossary entry?'=>'Czy chcesz usunąć ten wpis słownika?','Delete'=>'Usuń','Add new entry'=>'Dodaj nowy wpis','The phrase as it appears in the source text.'=>'Fraza tak jak pojawia się w tekście źródłowym.','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Jak powinna wyglądać w tłumaczeniu. Wpisz tę samą wartość co termin źródłowy, aby nakazać AI zachować ją dosłownie.','— Any source language —'=>'— Dowolny język źródłowy —','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Pozostaw puste dla nazw marek i terminów niezależnych od języka, które mają być egzekwowane bez względu na język tłumaczenia.','— Any target language —'=>'— Dowolny język docelowy —','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Pozostaw puste, aby zastosować tę pozycję do wszystkich języków docelowych — idealne dla nazw marek, skrótów i terminów, które muszą być zachowane dosłownie w każdym tłumaczeniu.','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Opcjonalny kontekst dla redaktorów (np. "ASIC = układ scalony specjalistyczny; zachować w języku angielskim w kontekstach technicznych").','Add entry'=>'Dodaj wpis','Limits'=>'Limity','Authors and above (edit_published_posts)'=>'Autorzy i wyżej (edytuj_opublikowane_posty)','Contributors and above — default (edit_posts)'=>'Współtwórcy i wyżej — domyślnie (edytuj_posty)','Editors and above (edit_others_posts)'=>'Redaktorzy i wyżej (edytuj_inne_posty)','Administrators only (manage_options)'=>'Tylko administratorzy (zarządzaj_opcjami)','AI Limits & Security'=>'Limity i bezpieczeństwo AI','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Ogranicz ilość korzystania z AI na stronie i ogranicz role użytkowników, które mogą wywołać płatne wywołania AI. Nakłada się na limit na poziomie użytkownika (30 żądań / minuta, na stałe), który już chroni przed niekontrolowanymi pętlami pojedynczego użytkownika.','Daily request limit'=>'Dzienny limit żądań','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Ogólny limit AI na stronie na UTC dzień (liczy zarówno tłumaczenia w Toolbar, jak i rewizje bloków). Licznik resetuje się o północy UTC. Ustaw na 0, aby wyłączyć limit.','Minimum role'=>'Minimalna rola','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Najniższa zdolność WordPress do wywoływania funkcji AI. Ograniczenie tego na stronach z wieloma autorami zapobiega uruchamianiu płatnych wywołań AI przez Współtwórców lub konta próbne. Nadpisz per funkcja za pomocą filtra linguaforge_required_capability.','Translation Limits'=>'Limity tłumaczeń','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Kontroluj, ile treści jest wysyłanych do AI i jak duża może być odpowiedź. Pozostaw puste, aby użyć wbudowanego domyślnego (pokazanego jako placeholder). Zwiększ te wartości, jeśli duże strony są obcinane; zmniejsz je, aby obniżyć koszty API.','Model tier'=>'Poziom modelu','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Jakość (domyślnie — Sonnet / GPT-4o / Gemini Pro)','Light (fast and cost-effective — Haiku / Flash)'=>'Lekki (szybki i ekonomiczny — Haiku / Flash)','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Który poziom modelu użyć do tłumaczenia pełnej strony. Jakość korzysta z modelu skonfigurowanego w tabeli modeli powyżej i jest zalecana do dokładnego, długiego tłumaczenia. Przełącz na Lekki tylko wtedy, gdy priorytetem jest szybkość lub koszt, a treść jest krótka.','Max output tokens'=>'Maksymalna liczba tokenów wyjściowych','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maksymalna liczba tokenów, które AI może wygenerować w jednej odpowiedzi tłumaczeniowej. Jeśli tłumaczenie jest cicho obcinane na końcu, zwiększ tę wartość. Domyślnie: 16 000.','Max input characters'=>'Maksymalna liczba znaków wejściowych','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maksymalna liczba znaków treści posta przekazywanej do AI. 0 oznacza brak limitu — pełna treść jest zawsze wysyłana (zalecane). Ustaw wartość różną od zera tylko wtedy, gdy twój dostawca ma ograniczone okno kontekstowe. Ostrzeżenie jest zapisywane w dzienniku błędów PHP za każdym razem, gdy treść jest przycinana.','Quick Translation'=>'Szybkie tłumaczenie','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Szybkie tłumaczenie jest używane w trybie fragmentów — krótkie fragmenty tłumaczone na żądanie z paska narzędzi, edytora lub wyskakujących okienek bloków. Używa osobnej, lżejszej konfiguracji od pełnoekranowego tłumaczenia, aby zachować szybkość i opłacalność odpowiedzi.','Light (default — fast and cost-effective)'=>'Lekki (domyślny — szybki i opłacalny)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Jakość (Sonnet / GPT-4o / Gemini Pro)','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Poziom Light korzysta z szybkiego modelu skonfigurowanego w tabeli modeli powyżej (domyślnie: Haiku / Flash). Przełącz na Jakość, jeśli potrzebujesz takiej samej dokładności tłumaczenia jak w trybie pełnoekranowym dla fragmentów.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maksymalna liczba tokenów, które AI może wygenerować na szybkie tłumaczenie. Domyślnie: 2000.','Maximum characters accepted from the input field. Default: 8 000.'=>'Maksymalna liczba znaków akceptowanych z pola wejściowego. Domyślnie: 8000.','Content Generator'=>'Generator treści','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Kontroluje budżet tokenów i limity wejścia dla funkcji Generatora treści AI. Pozostaw puste, aby użyć wbudowanych domyślnych ustawień.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maksymalna liczba tokenów, które AI może wygenerować na jedno uruchomienie. Zwiększ, jeśli pełne artykuły są obcinane. Domyślnie: 8192.','Max hints characters'=>'Maksymalna liczba znaków wskazówek','Maximum characters read from the Hints field. Default: 2 000.'=>'Maksymalna liczba znaków odczytanych z pola wskazówek. Domyślnie: 2000.','Max context characters'=>'Maksymalny kontekst','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maksymalna liczba znaków istniejącej treści posta przekazywanej do AI jako kontekst startowy, gdy nie podano wskazówek. Domyślnie: 6000.','Maintenance'=>'Utrzymanie','Language Overrides'=>'Nadpisywanie języka','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Prześlij skompilowane pliki .mo, aby nadpisać teksty wtyczek innych firm dla określonych lokalizacji — na przykład własne tłumaczenie VikBooking, które używa "mieszkanie" zamiast "pokój". Pliki muszą mieć nazwę zgodną z konwencją WordPress: {textdomain}-{locale}.mo (np. vikbooking-ca.mo). Są przechowywane w folderze uploads i przetrwają aktualizacje wtyczek.','Override file uploaded successfully.'=>'Nadpisanie pliku zostało pomyślnie przesłane.','Override file deleted.'=>'Plik nadpisania został usunięty.','No file was selected.'=>'Nie wybrano pliku.','Only .mo files are accepted.'=>'Akceptowane są tylko pliki .mo.','The upload failed — please try again.'=>'Przesyłanie nie powiodło się — spróbuj ponownie.','Could not save the file. Check that the uploads folder is writable.'=>'Nie można zapisać pliku. Sprawdź, czy folder uploads jest zapisywalny.','Invalid filename.'=>'Nieprawidłowa nazwa pliku.','Security check failed — file path is not permitted.'=>'Nieudana kontrola bezpieczeństwa — ścieżka pliku jest niedozwolona.','An unknown error occurred.'=>'Wystąpił nieznany błąd.','Text domain / locale'=>'Tekst domeny / lokalizacja','Files'=>'Pliki','Size'=>'Rozmiar','Delete all files for this override (both .mo and .po)?'=>'Usunąć wszystkie pliki dla tego nadpisania (zarówno .mo, jak i .po)?','No override files uploaded yet.'=>'Jeszcze nie przesłano żadnych plików nadpisujących.','Upload .mo file'=>'Prześlij plik .mo','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Akceptuje tylko skompilowane pliki .mo. Nazwa pliku musi mieć wzór {textdomain}-{locale}.mo. Przesłanie pliku o tej samej nazwie co istniejący spowoduje jego zastąpienie.','Upload Override'=>'Prześlij nadpisanie','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopiuj do bezpiecznej pamięci','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate przechowuje własne tłumaczenia w wp-content/languages/loco/ — lokalizacji, którą można cicho wyczyścić podczas aktualizacji WP, reinstalacji wtyczki lub usunięcia Loco Translate. Kopiowanie plików tutaj przenosi je do katalogu Lingua Forge i18n-overrides, który przetrwa te wszystkie zdarzenia i jest automatycznie ładowany przy każdym żądaniu.','File copied to safe storage successfully.'=>'Plik skopiowany do bezpiecznej pamięci pomyślnie.','Source file not found.'=>'Nie znaleziono pliku źródłowego.','Could not copy the file. Check that the uploads folder is writable.'=>'Nie można skopiować pliku. Sprawdź, czy folder uploads jest zapisywalny.','Invalid file reference.'=>'Nieprawidłowe odniesienie do pliku.','Type'=>'Typ','✓ In safe storage'=>'✓ W bezpiecznej pamięci','Copy to safe storage'=>'Kopiuj do bezpiecznej pamięci','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Jeszcze nie znaleziono własnych plików Loco Translate. Pojawią się tutaj po zapisaniu tłumaczenia w Loco Translate.','AI Cache'=>'Pamięć podręczna AI','Lingua Forge caches AI-generated translations, meta descriptions, excerpts, and generated content per-post so unchanged inputs do not re-trigger a paid API call. Cached entries are automatically invalidated when their inputs change. Clear the cache manually to reclaim database space, force a resync after switching providers or editing prompt templates, or troubleshoot a cache-related issue.'=>'Lingua Forge buforuje tłumaczenia generowane przez AI, meta opisy, fragmenty i wygenerowaną treść na poziomie posta, aby nie wywoływać ponownie płatnych wywołań API przy niezmienionych danych wejściowych. Zbuforowane wpisy są automatycznie unieważniane, gdy ich dane wejściowe się zmieniają. Wyczyść pamięć podręczną ręcznie, aby odzyskać miejsce w bazie danych, wymusić ponowną synchronizację po zmianie dostawcy lub edycji szablonów promptów, lub rozwiązać problem związany z pamięcią podręczną.','AI cache cleared. %d entry was removed.'=>'Pamięć podręczna AI wyczyszczona. %d wpis został usunięty.' . "\0" . 'Pamięć podręczna AI wyczyszczona. %d wpisów zostało usuniętych.' . "\0" . '','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Czy wyczyścić wszystkie zapisane wyniki AI? Przyszłe żądania będą wywoływać nowe wywołania API, aż do odbudowania pamięci podręcznej.','Clear AI Cache'=>'Wyczyść pamięć podręczną AI','Debug Files'=>'Pliki debugowania','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Gdy włączone jest logowanie debugowania (za pomocą przełącznika poniżej lub przez zdefiniowanie LINGUAFORGE_AI_DEBUG w wp-config.php), funkcje tłumaczenia i tłumaczenia szablonów FSE zapisują swoje surowe podpowiedzi AI i odpowiedzi na dysk w celach diagnostycznych. Użyj tej sekcji, aby monitorować ten output i wyczyścić go, gdy będziesz miał to, czego potrzebujesz — pliki mogą szybko się powiększać na dużych stronach. Skonfiguruj katalog docelowy za pomocą filtra linguaforge_debug_dir.','Debug files cleared. %d file was removed.'=>'Pliki debugowania wyczyszczone. Usunięto %d plik.' . "\0" . 'Pliki debugowania wyczyszczone. Usunięto %d plików.' . "\0" . '','Debug logging enabled.'=>'Logowanie debugowania włączone.','Debug logging disabled.'=>'Logowanie debugowania wyłączone.','Debug logging'=>'Logowanie debugowania','Write AI prompts and responses to disk for troubleshooting'=>'Zapisuj podpowiedzi i odpowiedzi AI na dysk w celach diagnostycznych','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Wymuszone włączenie przez stałą LINGUAFORGE_AI_DEBUG w wp-config.php. Usuń tę linię, aby kontrolować ten przełącznik stąd.','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Wymuszone wyłączenie przez stałą LINGUAFORGE_AI_DEBUG w wp-config.php. Usuń tę linię, aby kontrolować ten przełącznik stąd.','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Pliki trafiają do poniższego katalogu. Przydatne do diagnozowania problemów z tłumaczeniem — wyłącz po uzyskaniu potrzebnych danych, aby pliki się nie gromadziły. Możesz też wymusić to z wp-config.php za pomocą `define( \'LINGUAFORGE_AI_DEBUG\', true );`, co nadpisuje ten przełącznik.','Currently:'=>'Obecnie:','✓ Enabled'=>'✓ Włączone','✗ Disabled'=>'✗ Wyłączone','Directory'=>'Katalog','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtruj za pomocą linguaforge_debug_dir, aby przekierować wyjście debugowania do niepublicznej lokalizacji.','.txt file(s) in the directory'=>'.txt plik(i) w katalogu','Save Debug Setting'=>'Zapisz ustawienia debugowania','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Czy chcesz usunąć wszystkie pliki .txt w katalogu debugowania? Sam katalog pozostanie, aby przyszłe zapisy debugowania mogły się tam trafiać.','Clear Debug Files'=>'Wyczyść pliki debugowania','Per-block translation cache shared across posts. Configure on/off in Settings → Behavior. Stats below show what is currently cached; clearing forces every block to be re-translated on next request (useful after upgrading models or to recover database space).'=>'Pamięć podręczna tłumaczeń na poziomie bloków współdzielona między postami. Konfiguruj w Ustawieniach → Zachowanie. Statystyki poniżej pokazują, co jest obecnie w pamięci podręcznej; wyczyszczenie wymusza ponowne tłumaczenie każdego bloku przy następnym żądaniu (przydatne po aktualizacji modeli lub w celu odzyskania miejsca w bazie danych).','Translation Memory cleared. %d cached block was removed.'=>'Pamięć tłumaczeń wyczyszczona. Usunięto %d zbuforowanych bloków.' . "\0" . 'Pamięć tłumaczeń wyczyszczona. Usunięto %d zbuforowanych bloków.' . "\0" . '','Status'=>'Status','— toggle in Settings → Behavior.'=>'— przełącznik w Ustawienia → Zachowanie.','Cached blocks'=>'Zbuforowane bloki','Cumulative cache hits'=>'Kumulatywne trafienia w pamięć podręczną','(avg %.1f hits/block)'=>'(średnio %.1f trafień/blok)','Oldest entry'=>'Najstarszy wpis','Newest entry'=>'Najnowszy wpis','Approximate size'=>'Przybliżony rozmiar','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Wyczyścić całą pamięć tłumaczeń? Przyszłe tłumaczenia odbudują pamięć podręczną podczas ich wykonywania.','Clear Translation Memory'=>'Wyczyść pamięć tłumaczeń','Uninstall Behaviour'=>'Odinstaluj zachowanie','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Kontroluje, co się dzieje, gdy administrator usuwa wtyczkę z Plugins → Installed Plugins → Delete. Ustawienia wtyczki i pamięć podręczna AI są zawsze usuwane. Przydziały językowe i relacje tłumaczeń są domyślnie zachowywane, więc przypadkowe odinstalowanie lub reinstalacja mogą kontynuować tam, gdzie zostały przerwane.','Uninstall setting saved.'=>'Ustawienie odinstalowania zapisane.','Delete content data on uninstall'=>'Usuń dane zawartości podczas odinstalowania','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Usuń również przypisania językowe, relacje tłumaczeń, meta opisy, glosariusz i pamięć tłumaczeń podczas odinstalowania wtyczki.','Warning:'=>'Ostrzeżenie:','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Jeśli zaznaczysz, odinstalowanie wtyczki trwale usunie wszystkie przypisania językowe, relacje tłumaczeń, meta opisy, ustawienia na stronie, glosariusz AI i pamięć tłumaczeń dla każdego posta na tej stronie. Nie można tego cofnąć. Odznacz, jeśli chcesz całkowicie usunąć obsługę wielojęzyczności ze strony.','Save Uninstall Setting'=>'Zapisz ustawienie odinstalowania','Router'=>'Router','Primary language saved.'=>'Zapisano główny język.','Permalink rules flushed successfully.'=>'Pomyślnie wyczyszczono reguły permalinków.','Primary Language'=>'Główny język','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Główny język jest zawsze dostępny na głównym adresie Twojej strony — brak prefiksu URL w trybie ścieżki, brak subdomeny językowej w trybie subdomeny. Wszystkie pozostałe języki używają albo prefiksu /lang/ (np. example.com/de/), albo subdomeny językowej (np. de.example.com), w zależności od ustawienia struktury URL poniżej.','Primary language'=>'Główny język','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Po zmianie głównego języka, odśwież permalink (sekcja poniżej), aby zaktualizować trasowanie URL.','URL structure'=>'Struktura URL','Path prefix — example.com/de/'=>'Przedrostek ścieżki — example.com/pl/ lub example.com/de/ (w zależności od języka)','Subdomain — de.example.com/'=>'Subdomena — pl.example.com/ lub de.example.com/ (w zależności od języka)','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Tryb subdomen wymaga, aby Twój serwer internetowy kierował wszystkie subdomeny językowe (np. de.example.com) do tej instalacji WordPress. Po zmianie trybu odśwież ustawienia permalinków i wyczyść pamięć podręczną. Jeśli Twój adres URL główny zawiera www (np. www.example.com), użyj filtra lf_base_domain, aby ustawić podstawową domenę, tak aby subdomeny były poprawnie konstruowane.','Browser language redirect'=>'Przekierowanie języka przeglądarki','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Przekieruj odwiedzających do ich preferowanego języka na podstawie nagłówka Accept-Language przeglądarki','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Po włączeniu, odwiedzający po raz pierwszy, bez pliku cookie języka i bez prefiksu języka w URL, są przekierowywani do najbliższej pasującej wersji językowej. Przekierowanie jest pomijane, jeśli preferowany język przeglądarki nie znajduje się na liście aktywnych języków routera. Po wybraniu języka przez odwiedzającego za pomocą przełącznika, plik cookie ma pierwszeństwo, a nagłówek przeglądarki jest ignorowany przy kolejnych wizytach.','Save Router Settings'=>'Zapisz ustawienia routera','Flush Permalinks'=>'Wyczyść permalinki','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regeneruje reguły przepisywania WordPress, aby prefiksy URL, specyficzne dla języka slug i przepisywanie archiwów były zsynchronizowane. Konieczne po zmianie głównego języka lub dodaniu nowego wsparcia językowego.','Flush Permalink Rules'=>'Wyczyść reguły permalinków','Active Languages'=>'Aktywne języki','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Języki obecnie znane routerowi (pochodzące z zainstalowanych pakietów lokalizacyjnych WordPress oraz główny język). Zainstaluj dodatkowe pakiety językowe w poniższej sekcji, aby udostępnić więcej języków do routingu i tłumaczeń.','%d locale pack installed.'=>'Zainstalowano %d pakiet lokalizacyjny.' . "\0" . 'Zainstalowano %d pakietów lokalizacyjnych.' . "\0" . '','Install a Language'=>'Zainstaluj język','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Pobierz i zainstaluj pakiet językowy WordPress bezpośrednio z WordPress.org. Po instalacji lokalizacja będzie dostępna do routingu URL i workflow tłumaczeń AI. Lista dostępnych języków jest pobierana na żądanie — kliknij przycisk poniżej, aby ją załadować.','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Instalacja języków jest wyłączona na tym serwerze. Stała DISALLOW_FILE_MODS jest ustawiona w wp-config.php. Zainstaluj pakiety językowe ręcznie za pomocą WP-CLI: wp language core install de_DE','Load available languages'=>'Załaduj dostępne języki','— select a language —'=>'— wybierz język —','Install'=>'Zainstaluj','Language Setup'=>'Ustawienia języka','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Brak skonfigurowanych języków drugorzędnych. Zainstaluj pakiet językowy powyżej, aby włączyć szablony.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Wybierz język, aby zarządzać jego szablonami FSE, częściami szablonów i menu nawigacyjnymi.','Forbidden'=>'Zabronione','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Instalacja języków jest wyłączona na tym serwerze (ustawiono DISALLOW_FILE_MODS).','Invalid locale code.'=>'Nieprawidłowy kod lokalizacji.','Language %s installed successfully.'=>'Język %s został pomyślnie zainstalowany.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Niepowodzenie instalacji pakietu językowego. Język może być już zainstalowany, kod lokalizacji może być niepoprawny lub serwer może blokować zapisy plików.','Navigations'=>'Nawigacje','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Tłumaczenie nawigacji wymaga aktywnego dostawcy AI. Skonfiguruj klucz API w zakładce Klucze API.','Navigation'=>'Nawigacja','Action'=>'Akcja','Re-translate'=>'Ponowne tłumaczenie','CPT Block Patterns'=>'Wzory bloków CPT','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Wzory bloków zarejestrowane dla niestandardowych typów postów. Użyj przycisku Tłumacz, aby wygenerować wersję językową. Tłumaczona zawartość jest zapisywana tutaj i może być skopiowana do dowolnego posta CPT z edytora bloków lub użyta jako punkt wyjścia dla Wzoru synchronizowanego (Blok wielokrotnego użytku).','Pattern'=>'Wzór','Post Types'=>'Typy postów','✓ Translation saved'=>'✓ Tłumaczenie zapisane','View'=>'Zobacz','Template Parts'=>'Części szablonów','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Kopie części szablonów tematu specyficzne dla języka. Po utworzeniu, szablony są aktualizowane, aby odwoływały się do części specyficznej dla języka.','Part'=>'Część','Status / Actions'=>'Status / Działania','Fix Links'=>'Napraw linki','Fix Nav'=>'Napraw nawigację','Create'=>'Utwórz','Templates'=>'Szablony','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Szablony FSE utworzone z aktywnego motywu. Utwórz, a następnie dostosuj w Edytorze witryny.','Actions'=>'Działania','Fix Parts'=>'Napraw części','Create missing'=>'Utwórz brakujące','Translate all'=>'Przetłumacz wszystko','Fix all parts'=>'Napraw wszystkie części','Fix all links'=>'Napraw wszystkie linki','Anthropic (Claude)'=>'Anthropic (Claude)','OpenAI (GPT)'=>'OpenAI (GPT)','Google (Gemini)'=>'Google (Gemini)','Testing…'=>'Testowanie…','✓ Connection OK'=>'✓ Połączenie OK','✗ Failed:'=>'✗ Niepowodzenie:','No response from provider — check the error log for details.'=>'Brak odpowiedzi od dostawcy — sprawdź dziennik błędów po szczegóły.','Network error — could not reach the WordPress AJAX endpoint.'=>'Błąd sieci — nie można nawiązać kontaktu z punktem końcowym AJAX WordPress.','Loading…'=>'Wczytywanie…','Installing…'=>'Instalacja…','✓ Language installed.'=>'✓ Język zainstalowany.','✗ Error:'=>'✗ Błąd:','Creating…'=>'Tworzenie…','✓ All templates created.'=>'✓ Wszystkie szablony utworzone.','Some templates could not be created.'=>'Niektórych szablonów nie można utworzyć.','✓ All parts created.'=>'✓ Wszystkie części utworzone.','Some parts could not be created.'=>'Niektórych części nie można utworzyć.','✓ All translated.'=>'✓ Wszystko przetłumaczone.','Some translations failed.'=>'Niektóre tłumaczenia nie powiodły się.','Review carefully — links and slugs not updated.'=>'Dokładnie sprawdź — linki i slug nie zostały zaktualizowane.','Fixing…'=>'Naprawianie…','✓ Links fixed.'=>'✓ Linki naprawione.','Some link fixes failed.'=>'Niektóre naprawy linków nie powiodły się.','✓ Parts fixed.'=>'✓ Części naprawione.','Some part fixes failed.'=>'Niektóre naprawy części nie powiodły się.','✓ Nav refs fixed.'=>'✓ Naprawione odwołania nawigacyjne.','Some nav ref fixes failed.'=>'Niektóre naprawy odwołań nawigacyjnych nie powiodły się.','✓ Pattern translated.'=>'✓ Wzorzec przetłumaczony.','Pattern translation failed.'=>'Tłumaczenie wzorca nie powiodło się.','Hide'=>'Ukryj','Built-in preset instructions:'=>'Wbudowane instrukcje presetów:','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Brak wbudowanych instrukcji — każda funkcja AI korzysta z własnych dostrojonych domyślnych ustawień. Wypełnij poniższe pole Instrukcje niestandardowe, aby dodać własne zasady dla całej witryny.','Settings'=>'Ustawienia','You do not have permission to manage these settings.'=>'Nie masz uprawnień do zarządzania tymi ustawieniami.','Lingua Forge — Settings'=>'Lingua Forge — Ustawienia','Settings saved.'=>'Ustawienia zapisane.','Save Settings'=>'Zapisz ustawienia','Standard'=>'Standardowy','Technical / Scientific'=>'Techniczny / Naukowy','Legal / Compliance'=>'Prawny / Zgodność','Creative / Marketing'=>'Kreatywny / Marketing','Full Article'=>'Pełny artykuł','Introduction only'=>'Tylko wprowadzenie','Structured Outline'=>'Strukturalny plan','Generate Content'=>'Generuj treść','Hints'=>'Wskazówki','Key points, ideas, or structure to build from…'=>'Kluczowe punkty, pomysły lub struktura do zbudowania...','Tone'=>'Ton','Output'=>'Wynik','Generate Excerpt'=>'Wygeneruj fragment','Generate Meta Description'=>'Wygeneruj metaopis','Translate Content'=>'Tłumacz treść','Mode'=>'Tryb','Full post'=>'Pełny post','Translate chunk'=>'Tłumacz fragment','Target Language'=>'Język docelowy','Text to translate'=>'Tekst do tłumaczenia','Paste a footnote, sentence, or any snippet here…'=>'Wklej tutaj przypis, zdanie lub dowolny fragment…','Also generate meta description'=>'Również wygeneruj metaopis','Translated Names'=>'Tłumaczone nazwy','Name displayed in this language. Leave empty to use the source name.'=>'Nazwa wyświetlana w tym języku. Pozostaw puste, aby użyć nazwy źródłowej.','Too many AI requests. Please retry in %d seconds.'=>'Zbyt wiele żądań AI. Spróbuj ponownie za %d sekund.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Dzienne limity AI osiągnięte (%1$d żądań). Reset o %2$s UTC.','View Lingua Forge details'=>'Zobacz szczegóły Lingua Forge','View details'=>'Zobacz szczegóły','Visit plugin site'=>'Odwiedź stronę wtyczki','%d language not yet linked'=>'%d język jeszcze nie powiązany' . "\0" . '%d języków jeszcze nie powiązanych' . "\0" . '','This is the source page. Footnotes are edited directly in the block editor.'=>'To jest strona źródłowa. Przypisy są edytowane bezpośrednio w edytorze bloków.','No source page linked yet.'=>'Jeszcze nie powiązano strony źródłowej.','The source page has no footnotes.'=>'Strona źródłowa nie ma przypisów.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Te przypisy pochodzą ze strony źródłowej i są wyświetlane tutaj wyłącznie w celach informacyjnych. Dodaj je do tej strony za pomocą edytora bloków.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d lokalizowanych szablonów z motywu „%2$s” jest zachowanych w bazie danych, ale są obecnie nieaktywne. Ponownie staną się aktywne, jeśli ponownie aktywujesz ten motyw. Aby przenieść swoje tłumaczenia do nowego motywu, wygeneruj je ponownie za pomocą <strong>Ustawienia → Lingua Forge → Router → FSE scaffold</strong>.','Scanning posts for broken language links…'=>'Skanowanie postów w poszukiwaniu uszkodzonych linków językowych…','Re-scanning…'=>'Ponowne skanowanie…','Scan failed: '=>'Nieudane skanowanie: ','unknown error'=>'nieznany błąd','Scan request failed. Please try again.'=>'Żądanie skanowania nie powiodło się. Spróbuj ponownie.','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Nie znaleziono postów <strong>{lang}</strong>. Upewnij się, że wszystkie przetłumaczone posty mają ustawiony meta języka na <strong>{lang}</strong> w metaboxie języka.','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Nie znaleziono uszkodzonych linków ani niezgodności szablonów dla <strong>{lang}</strong>. Skanowano <strong>{scanned}</strong> postów i stron — wszystkie kontrole przeszły pomyślnie. Linki do części szablonów (nagłówek, stopka, pasek boczny) nie są tutaj uwzględnione — użyj przycisku Napraw części szablonów, aby sprawdzić je osobno.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> automatycznie naprawialnych linków','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> linków wymagających ręcznej weryfikacji','and'=>'i','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Znaleziono {parts} wśród <strong>{total}</strong> z <strong>{scanned}</strong> zeskanowanych postów dla <strong>{lang}</strong>.','Post'=>'Post','Links'=>'Linki','link(s)'=>'link(i)','Fix'=>'Napraw','✅ Fixed ({n})'=>'✅ Naprawiono ({n})','⚠ No changes — re-scan?'=>'⚠ Brak zmian — ponowne skanowanie?','⚠ No changes'=>'⚠ Brak zmian','❌ Failed'=>'❌ Niepowodzenie','Done — {done} of {total} post(s) fixed.'=>'Zakończono — naprawiono {done} z {total} postów.','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} nie miało wymienialnych linków — ponowne skanowanie w celu sprawdzenia)','Fixing {n} / {total}…'=>'Naprawa {n} / {total}…','URL could not be mapped to a post — check the link target exists'=>'Nie można przypisać URL do posta — sprawdź, czy cel linku istnieje','No {lang} translation registered (TRID missing)'=>'Nie zarejestrowano tłumaczenia {lang} (brak TRID)','Translation found but permalink could not be generated'=>'Znaleziono tłumaczenie, ale nie można wygenerować odnośnika','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> nieaktualna(e) ścieżka(e)','📍 Stale path (page moved)'=>'📍 Nieaktualna ścieżka (strona przeniesiona)','{n} stale path(s)'=>'{n} nieaktualna(e) ścieżka(e)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> problem(y) z szablonem','📄 Wrong template'=>'📄 Zły szablon','Expected: {expected}'=>'Oczekiwane: {expected}','Current: {current}'=>'Aktualne: {current}','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Szablon "{expected}" nie istnieje — najpierw utwórz go w Edytorze Stron.','Fix Template'=>'Napraw szablon','✅ Template fixed'=>'✅ Szablon naprawiony','Internal Link Fixer'=>'Naprawiacz linków wewnętrznych','Fix All'=>'Napraw wszystko','Re-scan'=>'Ponowne skanowanie','Language Switcher'=>'Przełącznik języków','Displays the Lingua Forge language switcher.'=>'Wyświetla przełącznik języków Lingua Forge.','Language'=>'Język','Display'=>'Wyświetlacz','Language label'=>'Etykieta języka','Icon only'=>'Tylko ikona','Icon + label'=>'Ikona + etykieta','Dropdown direction'=>'Kierunek rozwijanego menu','Down'=>'Dół','Up'=>'Góra','You do not have permission to read this post.'=>'Nie masz uprawnień do odczytu tego wpisu.','Post not found.'=>'Nie znaleziono wpisu.','Limit results to pages in the given Lingua Forge language code.'=>'Ogranicz wyniki do stron w podanym kodzie języka Lingua Forge.','Meta Description'=>'Meta opis','Using custom meta description.'=>'Używanie własnego meta opisu.','Prefilled from excerpt. Edit to override.'=>'Wstępnie wypełnione z fragmentu. Edytuj, aby nadpisać.','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Celuj w 120–160 znaków. Pozostaw puste, aby użyć zapasowego fragmentu.','↺ Refreshing…'=>'↺ Odświeżanie…','Review translation before applying'=>'Przejrzyj tłumaczenie przed zastosowaniem','Current title'=>'Aktualny tytuł','Translated title'=>'Tłumaczony tytuł','Current content (will be overwritten)'=>'Aktualna treść (zostanie nadpisana)','Translated content'=>'Tłumaczona treść','Footnotes payload (advanced)'=>'Dane odnośników (zaawansowane)','Generated meta description'=>'Wygenerowany meta opis','Saved to the meta description field when you apply.'=>'Zapisano w polu meta opisu po zastosowaniu.','Cancel'=>'Anuluj','Apply translation'=>'Zastosuj tłumaczenie','Generated Content'=>'Wygenerowana treść','Refine further:'=>'Dalsza poprawa:','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Dodaj instrukcje, aby ulepszyć szkic — np. skróć go, dodaj sekcję podsumowania, użyj bardziej formalnego rejestru, dodaj blok FAQ…','↺ Refine'=>'↺ Ulepszanie','Copy markup'=>'Kopiuj kod','Apply to Editor'=>'Zastosuj do Edytora','Copied ✓'=>'Skopiowano ✓','Applying…'=>'Zastosowanie…','Applied ✓'=>'Zastosowano ✓','Refining…'=>'Dopracowywanie…','Refinement failed — please try again.'=>'Nie udało się dopracować — spróbuj ponownie.','Refinement'=>'Dopracowywanie','✓ Refined — review the updated draft above.'=>'✓ Dopracowano — przejrzyj zaktualizowany szkic powyżej.','Request failed — please try again.'=>'Żądanie nie powiodło się — spróbuj ponownie.','The editor did not accept the content — please try again.'=>'Redaktor nie zaakceptował treści — spróbuj ponownie.','Save the post to persist changes.'=>'Zapisz wpis, aby zachować zmiany.','Apply failed — please try again.'=>'Nie udało się zastosować — spróbuj ponownie.','Copy'=>'Kopiuj','Apply to Meta Description'=>'Zastosuj do Opisu Meta','Generating…'=>'Tworzenie…','Generation failed.'=>'Niepowodzenie generowania.','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Treść wygenerowana — zobacz nakładkę, aby przejrzeć, dopracować i zastosować.','Request failed.'=>'Żądanie nie powiodło się.','cached'=>'pamięć podręczna','Translated to:'=>'Przetłumaczono na:','tone'=>'ton','Content generated'=>'Treść wygenerowana','Content ready'=>'Treść gotowa','footnote(s) translated — applied together with content.'=>'Przetłumaczono przypis(y) — zastosowano razem z treścią.','Chunk translated to:'=>'Fragment przetłumaczony na:','Chunk translated'=>'Fragment przetłumaczony','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Skopiuj wynik i wklej tam, gdzie jest to potrzebne (np. bezpośrednio do pola przypisu).','chars'=>'znaki','✓ Good length'=>'✓ Odpowiednia długość','⚠ Borderline'=>'⚠ Granica','✗ Too short'=>'✗ Za krótko','✗ Too long'=>'✗ Za długo','Target: 140–160 chars for optimal SERP display'=>'Docelowo: 140–160 znaków dla optymalnego wyświetlania w SERP','SEO character-count info'=>'Informacje o liczbie znaków SEO','↺ Refresh'=>'↺ Odśwież','Re-generates and updates the cached result.'=>'Ponownie generuje i aktualizuje zapisany wynik.','← Back'=>'← Wstecz','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Dodaj instrukcje, aby poprawić szkic — np. skróć go, dodaj sekcję podsumowania, użyj bardziej formalnego rejestru…','Improve writing'=>'Popraw pisanie','Make formal'=>'Uczyń formalnym'